function openTaskMenu(id){const task=state.tasks.find(t=>t.id===id);if(!task)return;const root=document.querySelector('#modal-root');root.innerHTML='<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><div class="modal-top"><h2>할 일 관리</h2><button class="close" data-close aria-label="닫기">×</button></div><div class="settings-list"><button class="button secondary full" data-task-edit>수정</button><button class="button secondary full" data-task-memo>메모 추가</button><button class="button ghost full" data-task-delete>삭제</button></div></section></div>';root.querySelector('[data-close]').onclick=()=>root.innerHTML='';root.querySelector('[data-task-edit]').onclick=()=>{root.innerHTML='';openTaskEditModal(id)};root.querySelector('[data-task-memo]').onclick=()=>{root.innerHTML='';openTaskMemoModal(id)};root.querySelector('[data-task-delete]').onclick=()=>{if(confirm('이 할 일을 삭제할까요?')){state.tasks=state.tasks.filter(t=>t.id!==id);save();root.innerHTML='';render();showToast('할 일을 삭제했어요')}}}
function openTaskEditModal(id){const task=state.tasks.find(t=>t.id===id);if(!task)return;const root=document.querySelector('#modal-root');root.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><div class="modal-top"><h2>할 일 수정</h2><button class="close" data-close aria-label="닫기">×</button></div><form id="task-edit-form"><label class="field-label">과제명</label><input class="input" name="title" required maxlength="50" value="${esc(task.title)}"/><div class="form-grid"><div><label class="field-label">마감일시</label><input class="input" name="due" type="datetime-local" required value="${esc(task.due)}"/></div><div><label class="field-label">시작 예정</label><input class="input" name="start" type="datetime-local" required value="${esc(task.start)}"/></div></div><div class="form-grid"><div><label class="field-label">예상 소요 시간</label><select class="select" name="hours"><option value="0.5" ${task.hours===0.5?'selected':''}>30분</option><option value="1" ${task.hours===1?'selected':''}>1시간</option><option value="2" ${task.hours===2?'selected':''}>2시간</option><option value="3" ${task.hours>=3?'selected':''}>3시간 이상</option></select></div><div><label class="field-label">중요도</label><select class="select" name="priority"><option ${task.priority==='보통'?'selected':''}>보통</option><option ${task.priority==='높음'?'selected':''}>높음</option></select></div></div><label class="field-label">메모</label><textarea class="textarea" name="memo">${esc(task.memo||'')}</textarea><div class="modal-actions"><button type="button" class="button ghost" data-close>취소</button><button class="button" type="submit">수정 저장</button></div></form></section></div>`;root.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>root.innerHTML='');root.querySelector('#task-edit-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.currentTarget);Object.assign(task,{title:d.get('title').trim(),due:d.get('due'),start:d.get('start'),hours:Number(d.get('hours')),priority:d.get('priority'),memo:d.get('memo').trim()});save();root.innerHTML='';render();showToast('할 일을 수정했어요')}}
function openTaskMemoModal(id){const task=state.tasks.find(t=>t.id===id);if(!task)return;const root=document.querySelector('#modal-root');root.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><div class="modal-top"><h2>메모 추가</h2><button class="close" data-close aria-label="닫기">×</button></div><form id="task-memo-form"><label class="field-label">${esc(task.title)}</label><textarea class="textarea" name="memo" maxlength="500" placeholder="할 일에 필요한 메모를 적어두세요">${esc(task.memo||'')}</textarea><div class="modal-actions"><button type="button" class="button ghost" data-close>취소</button><button class="button" type="submit">메모 저장</button></div></form></section></div>`;root.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>root.innerHTML='');root.querySelector('#task-memo-form').onsubmit=e=>{e.preventDefault();task.memo=new FormData(e.currentTarget).get('memo').trim();save();root.innerHTML='';render();showToast('메모를 저장했어요')}}
function openAppsModal(){const root=document.querySelector('#modal-root');const labels=['Instagram','YouTube','TikTok','X','Netflix'];let apps=labels.map(label=>({label,value:label}));try{const installed=JSON.parse(window.NativeMvp?.installedAppsJson?.()||'[]');if(installed.length)apps=installed.map(a=>({label:a.label,value:a.label}))}catch{}const selected=new Set(state.blocked);const body=`<p class="page-subtitle">휴대폰에 설치된 앱 중 잠깐 멀리하고 싶은 앱을 골라주세요.</p><div style="margin-top:13px;max-height:45vh;overflow:auto">${apps.map(a=>`<div class="app-chip"><label><input type="checkbox" name="blocked" value="${esc(a.value)}" ${selected.has(a.value)?'checked':''}/>${esc(a.label)}</label><span class="eyebrow">앱</span></div>`).join('')}</div><div class="notice">앱 사용 기록 권한을 허용한 뒤 집중을 시작하면 선택한 앱을 감지합니다.</div><button class="button full" id="save-apps">선택 저장</button>`;root.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><div class="modal-top"><h2>집중 방해 앱 선택</h2><button class="close" data-close aria-label="닫기">×</button></div>${body}</section></div>`;root.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>root.innerHTML='');root.querySelector('#save-apps').onclick=()=>{state.blocked=[...root.querySelectorAll('[name=blocked]:checked')].map(i=>i.value);save();root.innerHTML='';render();showToast('집중 방해 앱을 저장했어요')}}
function openModal(type,editId=null){const root=document.querySelector('#modal-root');let body='',title='';if(type==='task'){title='할 일 추가';body=`<form id="task-form"><label class="field-label">과제명</label><input class="input" name="title" required maxlength="50" placeholder="예: 발표 자료 초안 만들기"/><div class="form-grid"><div><label class="field-label">마감일시</label><input class="input" name="due" type="datetime-local" required value="${localDate(new Date(today.getFullYear(),today.getMonth(),today.getDate()+1,18,0))}"/></div><div><label class="field-label">시작 예정</label><input class="input" name="start" type="datetime-local" required value="${localDate(new Date(today.getFullYear(),today.getMonth(),today.getDate(),new Date().getHours()+1,0))}"/></div></div><div class="form-grid"><div><label class="field-label">예상 소요 시간</label><select class="select" name="hours"><option value="0.5">30분</option><option value="1" selected>1시간</option><option value="2">2시간</option><option value="3">3시간 이상</option></select></div><div><label class="field-label">중요도</label><select class="select" name="priority"><option>보통</option><option>높음</option></select></div></div><label class="field-label">메모 (선택)</label><textarea class="textarea" name="memo" placeholder="잊지 않도록 짧게 적어두세요"></textarea><div class="notice">시작 시간이 다가오면 카운트다운 알림을 보여드려요.</div><button class="button full" type="submit">할 일 저장하기</button></form>`}else if(type==='class'){const current=state.classes.find(c=>c.id===editId);title=current?'수업 수정':'수업 추가';body=`<form id="class-form"><label class="field-label">과목명</label><input class="input" name="title" required value="${esc(current?.title||'')}" placeholder="예: 미디어와 사회"/><label class="field-label">요일</label><select class="select" name="day">${weekdays.map((d,i)=>`<option value="${i}" ${(current?.day??selectedDay)===i?'selected':''}>${dayLabel(i)}</option>`).join('')}</select><div class="form-grid"><div><label class="field-label">시작 시간</label><input class="input" name="start" type="time" value="${current?.start||'09:00'}" required/></div><div><label class="field-label">종료 시간</label><input class="input" name="end" type="time" value="${current?.end||'10:30'}" required/></div></div><label class="field-label">강의실 (선택)</label><input class="input" name="room" value="${esc(current?.room||'')}" placeholder="예: 인문관 302"/><div class="modal-actions"><button type="button" class="button ghost" data-close>취소</button><button class="button" type="submit">${current?'수정 저장':'시간표 저장'}</button></div></form>`}else{title='집중 방해 앱 선택';const apps=['Instagram','YouTube','TikTok','X','Netflix','게임 앱'];body=`<p class="page-subtitle">잠깐 멀리하고 싶은 앱을 골라주세요.</p><div style="margin-top:13px">${apps.map(a=>`<div class="app-chip"><label><input type="checkbox" name="blocked" value="${a}" ${state.blocked.includes(a)?'checked':''}/>${a}</label><span class="eyebrow">앱</span></div>`).join('')}</div><div class="notice">실제 설치 앱 목록은 Android 권한을 연결한 뒤 불러올 수 있어요.</div><button class="button full" id="save-apps">선택 저장</button>`}
root.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><div class="modal-top"><h2>${title}</h2><button class="close" data-close aria-label="닫기">×</button></div>${body}</section></div>`;root.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>root.innerHTML='');root.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))root.innerHTML=''};
const tf=root.querySelector('#task-form');if(tf)tf.onsubmit=e=>{e.preventDefault();const d=new FormData(tf);state.tasks.push({id:crypto.randomUUID(),title:d.get('title').trim(),due:d.get('due'),start:d.get('start'),hours:+d.get('hours'),priority:d.get('priority'),memo:d.get('memo').trim(),done:false,snoozes:0});save();root.innerHTML='';go('tasks');showToast('할 일을 저장했어요')};const cf=root.querySelector('#class-form');if(cf)cf.onsubmit=e=>{e.preventDefault();const d=new FormData(cf);if(d.get('start')>=d.get('end')){showToast('종료 시간을 시작 시간 뒤로 설정해주세요');return}const day=+d.get('day'),start=d.get('start'),end=d.get('end'),collision=state.classes.find(c=>c.id!==editId&&c.day===day&&c.start<end&&c.end>start);if(collision){showToast(`'${collision.title}' 수업과 시간이 겹쳐요.`);return}const entry={id:editId||crypto.randomUUID(),day,start,end,title:d.get('title').trim(),room:d.get('room').trim()},idx=state.classes.findIndex(c=>c.id===editId);if(idx>=0)state.classes[idx]=entry;else state.classes.push(entry);save();selectedDay=day;root.innerHTML='';go('schedule');showToast(editId?'수업을 수정했어요':'시간표에 저장했어요')};const ab=root.querySelector('#save-apps');if(ab)ab.onclick=()=>{state.blocked=[...root.querySelectorAll('[name=blocked]:checked')].map(i=>i.value);save();root.innerHTML='';render();showToast('집중 방해 앱을 저장했어요')}}
document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>go(b.dataset.page)));document.querySelector('#settings-shortcut').onclick=()=>go('settings');document.querySelector('#account-shortcut').onclick=openAccountModal;renderAccountButton();document.addEventListener('cookietime-auth-change',event=>{authUser=event.detail?.user||null;renderAccountButton();if(document.querySelector('#account-modal'))openAccountModal()});document.addEventListener('click',event=>{if(event.target.closest('[data-open-account]')){openAccountModal();return}const button=event.target.closest('[data-gap-start]');if(!button)return;const startAt=new Date(button.dataset.gapStart),endAt=new Date(button.dataset.gapEnd);if(startAt<new Date())startAt.setTime(Date.now()+1000);if(startAt>=endAt){showToast('이미 지난 공강이라 시작 시간을 예약할 수 없어요.');return}const size=button.dataset.gapSize;let task=state.tasks.find(item=>item.id===button.dataset.gapTask&&!item.done);if(!task)task=state.tasks.find(item=>!item.done&&item.memo==='시간표 공강 추천으로 추가됨'&&item.start===localDate(startAt));if(!task){const title=size==='short'?'수업 핵심 내용 복습':size==='medium'?'공강 과제 정리':'공강 집중 시간',due=new Date(startAt);due.setHours(23,59,0,0);task={id:crypto.randomUUID(),title,due:localDate(due),start:localDate(startAt),hours:Math.max(.5,Math.round(((endAt-startAt)/3600000)*2)/2),priority:'보통',memo:'시간표 공강 추천으로 추가됨',done:false,snoozes:0};state.tasks.push(task)}else task.start=localDate(startAt);save();showToast(`${task.title} 시작 알림을 ${fmtTime(task.start)}에 예약했어요`);render()});
function pulse(){if(state.focus.active){if(!state.focus.deviation){state.focus.seconds++;state.focus.sessionSeconds=(Number(state.focus.sessionSeconds)||0)+1;grantFocusCookieRewards()}if(state.focus.deviation&&state.settings.vibration&&Array.isArray(state.settings.vibrationThresholds)){const elapsed=(Date.now()-(state.focus.deviationAt||Date.now()))/60000,stage=state.settings.vibrationThresholds.reduce((n,threshold,i)=>elapsed>=threshold?i+1:n,0);if(stage>state.focus.vibrationStage){state.focus.vibrationStage=stage;vibrateStage(stage)}}save();if(page==='focus'){if(state.focus.deviation){const breakTimer=document.querySelector('#focus-break-time');if(breakTimer){const elapsed=liveRestSeconds(),m=String(Math.floor(elapsed/60)).padStart(2,'0'),sec=String(elapsed%60).padStart(2,'0');breakTimer.textContent='쉬는 시간 '+m+':'+sec+' · 집중 일시정지'}}else render()}}const now=new Date();for(const t of state.tasks){if(t.done)continue;if(t.start&&state.settings.countdown){const delta=new Date(t.start)-now,mins=Math.round(delta/60000),leads=[...new Set([...(state.settings.countdownLeads||[10,5,3,1]),0])];if(leads.includes(mins)&&delta>=0&&delta<59000){const marker=`${t.id}-start-${mins}`;if(!sessionStorage.getItem(marker)){sessionStorage.setItem(marker,'1');if(mins===0){promptTaskStart(t.id);window.NativeMvp?.countdown?.(t.title,0,t.id,t.snoozes||0)}else{showToast(`${mins}분 뒤 시작해요 · ${t.title}`);window.NativeMvp?.countdown?.(t.title,mins,t.id,t.snoozes||0)}}}}if(state.settings.reminder){const dueDelta=new Date(t.due)-now;for(const mins of [1440,180]){const enabled=mins===1440?state.settings.reminder24h:state.settings.reminder3h;if(!enabled)continue;const remaining=Math.round(dueDelta/60000);if(remaining===mins&&dueDelta>=0&&dueDelta<59000){const marker=`${t.id}-due-${mins}`;if(!sessionStorage.getItem(marker)){sessionStorage.setItem(marker,'1');showToast(`${mins===1440?'하루':'3시간'} 뒤 마감이에요 · ${t.title}`)}}}}}}
window.refreshNativeSettings=()=>{if(page==='settings'||page==='focus')render();if((state.focus.active||state.settings.blockedMode!=='focus')&&window.NativeMvp?.hasUsageAccess?.()&&window.NativeMvp?.hasOverlayPermission?.())window.NativeMvp.startMonitoring()};timer=setInterval(pulse,1000);render();syncNativeState();

document.addEventListener('change',event=>{if(event.target.id==='bubble-frequency'){state.settings.bubbleIntervalMinutes=Number(event.target.value);save();showToast('말풍선 빈도를 저장했어요')}if(event.target.id==='streak-criterion'){state.settings.streakCriterion=event.target.value;updateStreaks();save();render()}if(event.target.id==='deviation-goal'){state.settings.dailyDeviationGoalMinutes=Number(event.target.value)||60;updateStreaks();save();render()}if(event.target.id==='usage-default'){state.settings.usageDefaultMinutes=Number(event.target.value)||15;save()}});
document.addEventListener('click',event=>{const answer=event.target.closest('[data-quiz-answer]');if(answer){const ok=markQuizComplete(Number(answer.dataset.quizAnswer));save();render();showToast(ok?'오늘의 미션을 기록했어요.':'다시 생각해봐요.');return}const day=event.target.closest('[data-record-date]');if(day){const key=day.dataset.recordDate,record=(state.dailyRecords||[]).find(r=>r.date===key),detail=document.querySelector('#day-record-detail');if(detail)detail.textContent=`${key} · ${record?.missionComplete?'미션 완료':'미션 미완료'} · ${record?.onTimeStart?'정시 시작 기록 있음':'정시 시작 기록 없음'} · 앱 이탈 ${Math.floor(deviationSecondsFor(key)/60)}분 · 완료한 할 일 ${record?.taskCompletions||0}개`;return}if(event.target.closest('[data-game-start]'))startExecutiveGame();const gem=event.target.closest('[data-gem]');if(gem)pickExecutiveGem(gem.dataset.gem)});
let executiveGame=null,executiveTicker=null;function startExecutiveGame(){clearInterval(executiveTicker);executiveGame={stage:1,score:0,rule:'color',startedAt:performance.now(),duration:10000};document.querySelector('#game-result').textContent='';updateExecutiveTimer();playExecutiveStage();executiveTicker=setInterval(updateExecutiveTimer,50)}function updateExecutiveTimer(){if(!executiveGame)return;const elapsed=performance.now()-executiveGame.startedAt,remaining=Math.max(0,executiveGame.duration-elapsed),timer=document.querySelector('#game-timer'),bar=document.querySelector('#game-time-progress');if(timer)timer.textContent=`남은 시간 ${(remaining/1000).toFixed(1)}초`;if(bar)bar.style.width=`${remaining/executiveGame.duration*100}%`;if(remaining<=0)finishExecutiveGame(false)}function finishExecutiveGame(success){if(!executiveGame)return;clearInterval(executiveTicker);executiveTicker=null;const timer=document.querySelector('#game-timer'),instruction=document.querySelector('#game-instruction'),board=document.querySelector('#game-board'),result=document.querySelector('#game-result');if(board)board.innerHTML='';if(timer)timer.textContent=`${success?'통과':'실패'} · ${(Math.max(0,performance.now()-executiveGame.startedAt)/1000).toFixed(2)}초`;if(instruction)instruction.textContent=success?'5판 모두 맞혔어요!':'10초 안에 5판을 모두 맞히지 못했어요. 다시 도전해보세요.';if(result)result.textContent=success?'타임어택 성공!':'다시 도전';executiveGame=null}function playExecutiveStage(){const game=executiveGame;if(!game)return;const colors=['red','blue','yellow'],labels={red:'빨간',blue:'파란',yellow:'노란'},expected=colors[Math.floor(Math.random()*colors.length)];game.expected=expected;document.querySelector('#game-instruction').textContent=`${game.stage}/5판 · ${labels[expected]}색을 선택하세요`;const order=[...colors];for(let i=order.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[order[i],order[j]]=[order[j],order[i]]}const board=document.querySelector('#game-board');board.innerHTML=`<div class="gem-row">${order.map(color=>`<button class="gem ${color}" data-gem="${color}" aria-label="${labels[color]}색">◆</button>`).join('')}</div>`}function pickExecutiveGem(color){const game=executiveGame;if(!game)return;if(performance.now()-game.startedAt>=game.duration){finishExecutiveGame(false);return}if(color!==game.expected){finishExecutiveGame(false);return}game.score++;game.stage++;if(game.stage>5)finishExecutiveGame(game.score===5&&performance.now()-game.startedAt<=game.duration);else playExecutiveStage()}
const encouragementMessages=['한 번에 하나씩, 충분히 잘하고 있어요.','조금씩 쌓이는 중이에요.','지금의 집중이 좋은 흐름을 만들어요.','잠깐 숨을 고르고 다시 가도 괜찮아요.'];
setInterval(()=>{if(!state.focus.active||state.focus.deviation||!state.settings.character)return;const now=Date.now(),interval=(Number(state.settings.bubbleIntervalMinutes)||15)*60000;if(now-(state.focus.speechAt||state.focus.sessionStartedAt||now)<interval)return;let next=encouragementMessages[Math.floor(Math.random()*encouragementMessages.length)];if(next===state.focus.speech)next=encouragementMessages[(encouragementMessages.indexOf(next)+1)%encouragementMessages.length];state.focus.speech=next;state.focus.speechAt=now;save();if(page==='focus')render()},5000);
function classEndPoll(){if(state.settings.classEndReminders===false)return;const now=new Date(),minute=`${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`,todayList=todayClasses();for(const cls of todayList){if(cls.end!==minute)continue;const next=todayList.find(item=>item.start===cls.end);if(next)continue;const marker=`class-end-${dayKey()}-${cls.id}`;if(sessionStorage.getItem(marker))continue;sessionStorage.setItem(marker,'1');openClassEndPrompt(cls)}}
function openClassEndPrompt(cls){const root=document.querySelector('#modal-root');root.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><div class="modal-top"><h2>수업이 끝났어요</h2><button class="close" data-close>×</button></div><p class="page-subtitle">${esc(cls.title)}에서 할 일이 생겼나요? 제목과 마감만 빠르게 기록할 수 있어요.</p><form id="class-end-task"><label class="field-label">할 일 제목<input class="input" name="title" required maxlength="50" placeholder="예: 강의 노트 정리"/></label><label class="field-label">마감일시<input class="input" name="due" type="datetime-local" required value="${localDate(new Date(Date.now()+86400000))}"/></label><div class="modal-actions"><button type="button" class="button ghost" data-skip>나중에</button><button class="button" type="submit">빠르게 추가</button></div></form></section></div>`;root.querySelectorAll('[data-close],[data-skip]').forEach(b=>b.onclick=()=>root.innerHTML='');root.querySelector('#class-end-task').onsubmit=e=>{e.preventDefault();const data=new FormData(e.currentTarget),title=String(data.get('title')).trim();state.tasks.push({id:crypto.randomUUID(),title,due:data.get('due'),start:localDate(new Date()),hours:1,priority:'보통',memo:'수업 종료 알림에서 빠르게 추가',done:false,snoozes:0});save();root.innerHTML='';showToast('할 일을 추가했어요')}}
setInterval(classEndPoll,15000);

window.openMissionFromOverlay=()=>go('missions');
window.openClassEndFromNotification=title=>openClassEndPrompt({title});
